	FERMENTING_MOONLIGHT_MEAD_STATE_2(36),
	MOONLIGHT_MEAD(37),
	MATURE_MOONLIGHT_MEAD(38),

	/* Axeman's Folly */
	OAK_ROOTS(40),
	FERMENTING_AXEMANS_FOLLY_STATE_1(41),
	FERMENTING_AXEMANS_FOLLY_STATE_2(42),
	AXEMANS_FOLLY(43),
	MATURE_AXEMANS_FOLLY(44),

